final class ReportCsv
{
    public const HEADER = 'user,model,tokens_input,tokens_output,tokens_cache_read,tokens_cache_write,cost_usd';

    /**
     * @param list<array{user:string,model:string,in:int,out:int,cr:int,cw:int,cost:Money}> $rows sorted
     */
    public static function render(array $rows, array $total): string
    {
        $lines = [self::HEADER];
        foreach ($rows as $r) {
            $lines[] = implode(',', [self::field($r['user']), self::field($r['model']), $r['in'], $r['out'], $r['cr'], $r['cw'], $r['cost']->format(6)]);
        }
        $lines[] = implode(',', ['TOTAL', '', $total['in'], $total['out'], $total['cr'], $total['cw'], $total['cost']->format(6)]);
        return implode("\n", $lines) . "\n";
    }

    private static function field(string $v): string
    {
        return str_contains($v, ',') || str_contains($v, '"') || str_contains($v, "\n") || str_contains($v, "\r")
            ? '"' . str_replace('"', '""', $v) . '"'
            : $v;
    }
}
