private function parseRates(array $rates, PriceUnit $unit, int $no, string $ctx): array
{
    $required = $unit->requiredRateKeys();
    $result = [];
    foreach ($required as $key) {
        if (!array_key_exists($key, $rates) || !is_string($rates[$key]) || preg_match('/^\d{1,18}(\.\d{1,6})?$/', $rates[$key]) !== 1) {
            throw new ImportException("price[{$no}].rates: key '{$key}' is required, must be a non-negative decimal string (up to 6 decimal places)");
        }
        $result[$key] = $rates[$key];
    }
    $extra = array_diff(array_keys($rates), $required);
    if ($extra !== []) {
        throw new ImportException("price[{$no}].rates: unknown keys: " . implode(', ', array_map('strval', $extra)));
    }
    return $result;
}
