final class CatalogSnapshot
{
    /**
     * @param array<string, Provider> $providersByCode
     * @param array<string, Model> $modelsByKey        // "provider\0model"
     * @param array<string, list<PriceRow>> $priceRowsByModelKey // sorted valid_from DESC
     */
    private function __construct(
        private readonly array $providersByCode,
        private readonly array $modelsByKey,
        private readonly array $priceRowsByModelKey,
    ) {}

    public static function load(EntityManagerInterface $em): self
    {
        $providersByCode = [];
        foreach ($em->getRepository(Provider::class)->findAll() as $p) {
            $providersByCode[$p->getCode()] = $p;
        }
        $modelsByKey = [];
        foreach ($em->getRepository(Model::class)->findAll() as $m) {
            $modelsByKey[$m->getProvider()->getCode() . "\0" . $m->getCode()] = $m;
        }
        $rows = $em->createQuery(
            'SELECT pr FROM App\Entity\PriceRow pr JOIN pr.model m JOIN m.provider p ORDER BY p.code ASC, m.code ASC, pr.validFrom ASC'
        )->getResult();
        $byKey = [];
        foreach ($rows as $row) {
            $key = $row->getModel()->getProvider()->getCode() . "\0" . $row->getModel()->getCode();
            $byKey[$key][] = $row;
        }
        foreach ($byKey as &$list) {
            usort($list, static fn (PriceRow $a, PriceRow $b) => $b->getValidFrom() <=> $a->getValidFrom());
        }
        return new self($providersByCode, $modelsByKey, $byKey);
    }

    public function findPriceRow(string $providerCode, string $modelCode, \DateTimeInterface $ts): ?PriceRow
    {
        foreach ($this->priceRowsByModelKey[$providerCode . "\0" . $modelCode] ?? [] as $row) {
            if ($row->getValidFrom() <= $ts) {
                return $row;
            }
        }
        return null;
    }

    public function offPeakFor(string $providerCode): ?OffPeakWindow
    {
        $provider = $this->providersByCode[$providerCode] ?? null;
        if ($provider === null || $provider->getOffPeakWindowStart() === null || $provider->getOffPeakWindowEnd() === null || $provider->getOffPeakMultiplier() === null) {
            return null;
        }
        return new OffPeakWindow($provider->getOffPeakWindowStart(), $provider->getOffPeakWindowEnd(), $provider->getOffPeakMultiplier());
    }
}
```

